using System.Text.Json;
using System.Text.Json.Serialization.Metadata;

var options = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver()
};

// 1) Strongly-typed retrieval — returns JsonTypeInfo<Person> directly.
JsonTypeInfo<Person> personInfo = options.GetTypeInfo<Person>();
Console.WriteLine($"Got typed metadata for: {personInfo.Type.Name}");

// 2) Probe without throwing — TryGetTypeInfo returns false if unavailable.
if (options.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? found))
    Console.WriteLine($"TryGetTypeInfo succeeded for Person (kind: {found!.Kind})");
else
    Console.WriteLine("TryGetTypeInfo: Person metadata not available");

// Demonstrate the "not available" path using an options instance with no resolver.
var empty = new JsonSerializerOptions { TypeInfoResolver = null };

if (empty.TryGetTypeInfo(typeof(Person), out _))
    Console.WriteLine("Unexpected: found metadata in empty options");
else
    Console.WriteLine("TryGetTypeInfo correctly returned false for empty resolver");

record Person(string Name, int Age);

